%[text] %[text:anchor:T_360F0929] # EEG Artifacts
%[text] This script investigates how tACS stimulation artifacts affect EEG/LFP analysis and shows results for FASTR, FBAR, and RBAR algorithms.
%[text:tableOfContents]{"heading":"Table of Contents"}
%%
%[text] %[text:anchor:H_D32E8D0B] ## Setup Simulation
%[text] First define the stimulation and recording parameters.
run('../startup.m'); % Make sure all toolboxes are on the path
defaults = [];
defaults.reproducible              = true;    % Fix the random number generator to get reproducible results
%[text] Stimulation Equipment:
defaults.stimulatorSamplingRate    = 1e3;     % 1 kHz 
defaults.currentResolution         = 1e-6;    % 1 muA

%[text] Recording equipment (assuming essentially a linear amplifier for the signals simulated here).
defaults.recordingSamplingRate     = 5e3;     % 5kHz
defaults.adcLinearRange            = 200e-3;  % [V] Range over which the amplifier is linear
defaults.adcNonlinearity           = 100;     % linear inside the range,saturation outside
defaults.adcRange                  = 200e-3;  % The range of the ADC; bits are distributed evenly across this +/- range.
defaults.adcBitDepth               = 24;      % Number of bits in the ADC
defaults.adcGain                    = 1;      % Amplifier gain


defaults.highPass                  = 0.01;    % Analog filter of the recording amplifier
defaults.lowPass                   = 100;     % 
%[text] Experiment:
defaults.duration                  = 2*60;   % 2 min of data
defaults.tacsAmplitude             = 1e-3;   % 1 mA 
defaults.resistance                = 15;     % 15 Ohm: 1 mA - > 15 mV artifact
defaults.tacsFrequency             = 10;     % 10 Hz
%[text] Neural Signals: background noise plus an oscillation near 24 Hz.
defaults.additive                  = 100e-6;   % Background Noise stdev
defaults.lfpFrequency              = 24;       % Simulated oscillation peak frequency
defaults.lfpAmplitude              = 10e-6;    % Oscillation peak amplitude
defaults.lfpPeakWidth              = 1;        % Oscillation bandwidth.
%[text] And setup the base parameters for artifiact removal
ar = [];
ar.recordingSamplingRate = defaults.recordingSamplingRate; % Match to the recording
ar.segmentDuration       = 3;
ar.tacsFrequency         = defaults.tacsFrequency;
ar = namedargs2cell(ar); % For easy reuse below.
%[text] Setup the parameters for three artifact removal algorithms to explore.

fastr = [];
fastr.name = "FASTR";
fastr.options.slack = 5e-3;
fastr.options.nrSegsPerWindow = 10;
fastr.options.pcaNr = 2;
fastr.options.pcaVarExplained = Inf;
fastr.options.pcaNrSegsPerWindow = Inf;
fastr.options.referenceSegment = 1;

fbar= [];
fbar.name = "FBAR";
fbar.options.frequencyLimits = [-1 1];

rbar = [];
rbar.name = "RBAR";
rbar.options = [];
%%
%[text] %[text:anchor:H_DDD99D7B] ## Recovering neural signals and background
%[text] Create the artSim object using the default parameters defined above.
A = artSim(defaults);
A.sim;
%[text] Now A.vContaminated has the simulated time series. Generate a figure, run artifact removal, and show coarse (1 Hz) spectral results.
[~,axs4] = fig('Name','Fig4','paperCols',2,'height',10,'nrRows',3,'nrCols',4,'byColumn',true); %[output:63d78f12]
frequencyResolution = 1;
%[text] %[text:anchor:H_218F3721] ### FASTR
%[text] Template based artifact removal 
[resultsFastr] = artifactRemoval(A.vContaminated,fastr,ar{:});
analyzeEEG(A,resultsFastr.signal,freqRes=frequencyResolution,axs=axs4(1,1:3),legend=false); %[output:63d78f12]
%[text] ### FBAR
%[text] Fourier based artifact removal
resultsFbar = artifactRemoval(A.vContaminated,fbar,ar{:});
analyzeEEG(A,resultsFbar.signal,freqRes=frequencyResolution,axs=axs4(2,1:3),legend=false); %[output:63d78f12]
%[text] %[text:anchor:H_AAE631F7] ### RBAR
%[text] Regression based artifact removal:
resultsRbar= artifactRemoval(A.vContaminated,rbar,ar{:},vRecordTcs = A.vRecordTcs);
analyzeEEG(A,resultsRbar.signal,freqRes=frequencyResolution,axs=axs4(3,1:3),legend=false); %[output:63d78f12]
%[text] 
frequencyResolution = 0.1;
analyzeEEG(A,resultsFastr.signal,freqRes=frequencyResolution,axs=[gobjects(1,2) axs4(1,4)],legend=false); %[output:63d78f12]
analyzeEEG(A,resultsFbar.signal,freqRes=frequencyResolution,axs=[gobjects(1,2) axs4(2,4)],legend=false); %[output:63d78f12]
analyzeEEG(A,resultsRbar.signal,freqRes=frequencyResolution,axs=[gobjects(1,2) axs4(3,4)],legend=false); %[output:63d78f12]
ylim(axs4(:,[3 4]),[-40 40]) %[output:63d78f12]
%[text] The first columnshows a 100 ms snippet of the simulated neural signals (red) and recovered signal (green) on the left axis. The artfiact (blue) is orders of magnitude larger and shown on the right axis. Some mismatches between ground truth and recovered signals are visible in these snippets. 
%[text] The mismatch is easier to see in the spectral domain (second column); mismatches are biggest near the tACS frequency, but also spread across the specrum.  The third column expresses the mismatch as a percentage of ground truth signal; FASTR has residual errors across the spectrum, FBAR & RBAR perform better, recovering most of the spectrum, except for a band around the tACS frequency ("forbidden zones").
%[text] The peak in the FBAR error spectrum at 30 Hz is a consequence of the discretization of the stimulation current; this creates an artifact at the (odd) harmonics of the 10Hz tACS frequency, which FBAR does not remove becuase it only removes the fundamental. While this could be addressed by removing harmonics of the tACS frequency as well, that would come at the cost of additional forbidden zones.
%[text] The fourth column illustrates that relatively minor changes in the analysis pipeline can result in qualitatively different interpretations of the results. The only difference was a change in the frequency resolution of the display (no change in the artifact removal algorithms). This high resolution analysis reveals persistent errors in FASTR and, to a somewhat lesser extent, in FBAR,
%%
%[text] %[text:anchor:H_370D044C] ## Impedance Artifacts tACS
%[text] Physiological artifacts such as heartbeats, sweating, or breathing change impedance and interact multiplicatively with the signal. FASTR has a hard time recovering any underlying signals.
%[text] Keeping the neural signals from above, but adding an artifact that rhytmically (`o.zFrequency`) changes the impedance sinusoidally (maybe a reasonable approximation for respiration not so much for a heartbeat), The maximum change in the impedance is defined (as a fraction) by `o.zAmplitude.`
A            = artSim(defaults); % Start fresh %[output:186705fd]
A.zFrequency = 18/60;  % 18 breaths per minute
A.zAmplitude = 0.05;  % The artifact changes the impedance by 5%.
%[text] Run the simulation
A.sim;
%[text] 
[~,axs] = fig('Name','Fig6','paperCols',1.5,'height',9,'nrRows',2,'nrCols',2,'byColumn',false);

frequencyResolution = 0.1;
resultsFastr = artifactRemoval(A.vContaminated,fastr,ar{:});
analyzeEEG(A,resultsFastr.signal,freqRes=frequencyResolution,axs=[gobjects(1,2) axs(1,1)],legend=false);
resultsRbar= artifactRemoval(A.vContaminated,rbar,ar{:},vRecordTcs = A.vRecordTcs);
analyzeEEG(A,resultsRbar.signal,freqRes=frequencyResolution,axs=[gobjects(1,2) axs(1,2)],legend=false);
%[text] Next we simulate a impedance modulation that models the ballistic artifacts expected from a heartbeat. This uses an ECG recording and a simple body resonance model to simulate the ballistic impedance changes. See `zHeartbeat.m` for details.
%A      = artSim(eegDefaults); % Start fresh
A.zFun = @zHeartbeat ;

A.rng               % Reset rng if .reproducible
A.reset;            % Start fresh
A.simLfp;           % 1. Generate LFP/EEG .
A.simTCS;           % 2. Generate the TCS voltage
A.simRecording;     % 3. Simulate recording


resultsFastr = artifactRemoval(A.vContaminated,fastr,ar{:});
analyzeEEG(A,resultsFastr.signal,freqRes=frequencyResolution,axs=[gobjects(1,2) axs(2,1)],legend=false);
resultsRbar= artifactRemoval(A.vContaminated,rbar,ar{:},vRecordTcs = A.vRecordTcs);
analyzeEEG(A,resultsRbar.signal,freqRes=frequencyResolution,axs=[gobjects(1,2) axs(2,2)],legend=false);

ylim(axs,[-40 40])
%[text] Clearly FASTR (a,c) does not recover the neural signal of either sinusoidal/breathing (a) or pulsed/heartbeat (b) impedance artifacts; the multiplicative interactions between physiological artifacts and the true neural signal results in spurious signals across the entire spectrum.  Noury et al explain why this should happen and why there are two prominent peaks in a).  RBAR gets rid of most artifacts and only has a small forbidden zone near the tACS frequency. FBAR (not shown) has the same kind of issues as FASTR.
%[text] 
%%
%[text] ## Imedance Artifacts tDCS
%[text] As long as recordings exclude the ramp up and ramp down periods, the DC current generated by tDCS does not introduce neural artifacts on its own (although the presence of the device near the recording could introduce additional noise).  
%[text] However, impedance artifacts induced by physiological changes such as heartbeats can result in spurious neural signals. 
A                           = artSim(defaults);      % Start fresh
A.tdcsMean                  = 1e-3;         % Add DC
A.tacsAmplitude             = 0;            % Turn off AC
%A.lfpAmplitude              = 100e-6;    % Oscillation peak amplitude
A.resistance =1;

A.zFun  =  @zHeartbeat;
A.zAmplitude = 0.05;  % The artifact changes the impedance by 5%.

[~,axs] = fig('Name','Fig7','paperCols',1.5,'height',9,'nrRows',2,'nrCols',2,'span',{[1, 2 1],[2,1,1],[4,1,1]}); %[output:9aaddddc]
%[text] Zoom in on the timecourse near a heartbeat to illustrate the effect. To illustrate the heartbeat effect, remove the background activity.
tlim = [0.35 0.65];
A.additive                  = 0;
A.sim;

resultsNop = artifactRemoval(A.vContaminated,fastr,ar{:});
analyzeEEG(A,resultsNop.signal,freqRes=1,axs=[axs(1) gobjects(1,2)],legend=false,tlim=tlim,lineWidth=1); %[output:9aaddddc]

%[text] Restore the background activity and show the error spectra.
A.additive  =  defaults.additive;
A.sim;

resultsNop = artifactRemoval(A.vContaminated,struct('name','nop'),ar{:});
analyzeEEG(A,resultsNop.signal,freqRes=1,axs=[gobjects(1,2) axs(2)],legend=false,tlim=tlim,lineWidth=1); %[output:9aaddddc]

resultsRbar = artifactRemoval(A.vContaminated,rbar,recordingSamplingRate = A.recordingSamplingRate,segmentDuration=A.duration,vRecordTcs = A.vRecordTcs);

analyzeEEG(A,resultsRbar.signal,freqRes=1,axs=[gobjects(1,2) axs(3)],legend=false,tlim=tlim,lineWidth=1); %[output:9aaddddc]

yylinkaxes(axs([2 3])); %[output:9aaddddc]

%[text] Overlay the heartbeat for illustration (scaled to the range of the plot).
z = A.zFun(A);
axes(axs(1)) %[output:9aaddddc]

yyaxis right
x =axs(1).Children.XData;
y =axs(1).Children.YData;
cla %[output:9aaddddc]

stay  = A.tSimulate>tlim(1) & A.tSimulate < tlim(2);
h = plot(A.tSimulate(stay)-min(A.tSimulate(stay)),z(stay),'c-','LineWidth',1); %[output:9aaddddc]
%axs(1).Color = 0.95*ones(1,3);
axs(1).YAxis(2).Color = 'c'; %[output:9aaddddc]
ylim(1+ A.zAmplitude*[-1 1]) %[output:9aaddddc]
set(gca,'YTick',1+ A.zAmplitude*[-1 1]) %[output:9aaddddc]
yyaxis left %[output:9aaddddc]
delete(axs(1).Children(2)); %[output:9aaddddc]
plot(x,y,'b-') %[output:9aaddddc]

legend([axs(1).Children([1 3]);h], 'Neural','Recorded','CBA','Location','none','Position',[0.1283 0.1179 0.1914, 0.1118]) %[output:9aaddddc]


